import { notFound } from "next/navigation";
import { getOrgSchoolMeta } from "../../_queries/get-org-school-meta";
import { getSchoolOverviewData } from "./_queries/get-school-overview";
import { SchoolOverviewShell } from "./_components/school-overview-shell";

type Props = { params: Promise<{ schoolId: string }> };

export default async function SchoolOverviewPage({ params }: Props) {
  const { schoolId } = await params;
  const [meta, data] = await Promise.all([
    getOrgSchoolMeta(schoolId),
    getSchoolOverviewData(schoolId),
  ]);

  if (!meta.ok) notFound();

  return (
    <SchoolOverviewShell
      school={meta.school}
      memberCount={data.memberCount}
      pendingCount={data.pendingCount}
      principalName={data.principalName}
    />
  );
}

