"use client";

import { Button } from "@/components/ui/button";
import { useI18n } from "@/i18n/client-provider";
import {
  ArrowRightIcon,
  PaperPlaneTiltIcon,
  UsersThreeIcon,
  WarningIcon,
} from "@phosphor-icons/react";
import Link from "next/link";
import { SchoolMeta } from "../../../_lib/types";
import { SchoolLogo } from "../../../_components/school-logo";
import { StatCard } from "../../../_components/stat-card";
import { SchoolSubnav } from "../../_components/school-subnav";

type Props = {
  school: SchoolMeta;
  memberCount: number;
  pendingCount: number;
  principalName: string | null;
};

export function SchoolOverviewShell({
  school,
  memberCount,
  pendingCount,
  principalName,
}: Props) {
  const t = useI18n();
  const copy = t.dashboard.organization.school_overview;

  return (
    <>
      <SchoolSubnav schoolId={school.id} />
      <div className="flex flex-col gap-6 p-4 md:p-6">
        <header className="flex items-start gap-4">
          <SchoolLogo src={school.logo_url} name={school.name} size="lg" />
          <div className="flex min-w-0 flex-col gap-0.5">
            <h1 className="text-[20px] font-semibold tracking-tight text-foreground leading-tight">
              {school.name}
            </h1>
            {school.country && (
              <p className="text-[13px] text-muted-foreground">{school.country}</p>
            )}
            {!principalName && (
              <div className="mt-1 flex items-center gap-1 text-[12px] text-amber-600 dark:text-amber-500">
                <WarningIcon size={12} weight="fill" />
                {copy.no_principal}
              </div>
            )}
          </div>
        </header>

        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
          <StatCard
            label={copy.principal}
            value={principalName ?? "—"}
            tone={principalName ? "default" : "muted"}
          />
          <StatCard label={copy.members} value={memberCount} />
          <StatCard label={copy.pending} value={pendingCount} />
        </div>

        <div className="flex flex-col gap-3 rounded-xl border border-border bg-card p-4">
          <h2 className="text-[12px] font-medium text-muted-foreground">
            {copy.quick_actions}
          </h2>
          <div className="flex flex-wrap gap-2">
            <Button asChild variant="outline" size="sm">
              <Link href={`/organization/${school.id}/staff`}>
                <UsersThreeIcon size={13} weight="bold" />
                {copy.action_staff}
                <ArrowRightIcon size={11} weight="bold" />
              </Link>
            </Button>
            {!principalName && (
              <Button asChild size="sm">
                <Link href={`/organization/${school.id}/staff?invite=principal`}>
                  <PaperPlaneTiltIcon size={13} weight="bold" />
                  {copy.action_invite_principal}
                </Link>
              </Button>
            )}
          </div>
        </div>
      </div>
    </>
  );
}

import { Database } from "@/lib/supabase/types";

type Role = Database["public"]["Enums"]["user_role"];

export const CAPABILITIES = [
  "lessons.upload",
  "lessons.read.own",
  "lessons.read.school",
  "lessons.read.organization",
  "lessons.share",
  "lessons.assign",

  "members.read.school",
  "members.read.organization",

  "invitations.send.teacher",
  "invitations.send.hod",
  "invitations.send.principal",

  "schools.manage.own",
  "schools.manage.organization",

  "organization.manage",

  "billing.personal",
  "billing.school",
  "billing.organization",
] as const;

export type Capability = (typeof CAPABILITIES)[number];

const MATRIX: Record<Role, Capability[]> = {
  teacher: [
    "lessons.upload",
    "lessons.read.own",
    "lessons.share",
    "billing.personal",
  ],
  head_of_department: [
    "lessons.upload",
    "lessons.read.own",
    "lessons.read.school",
    "lessons.share",
    "members.read.school",
    "invitations.send.teacher",
  ],
  principal: [
    "lessons.upload",
    "lessons.read.own",
    "lessons.read.school",
    "lessons.assign",
    "members.read.school",
    "invitations.send.teacher",
    "invitations.send.hod",
    "schools.manage.own",
    "billing.school",
  ],
  org_admin: [
    "lessons.read.organization",
    "members.read.organization",
    "members.read.school",
    "invitations.send.principal",
    "schools.manage.organization",
    "organization.manage",
    "billing.organization",
  ],
};

export function can(
  cap: Capability,
  profile: { role: Role | null; school_id: string | null },
): boolean {
  if (!profile.role) return false;

  const hasBaseCapability = MATRIX[profile.role]?.includes(cap);
  if (!hasBaseCapability) return false;

  if (cap === "billing.personal" && profile.school_id !== null) {
    return false;
  }

  return true;
}

