"use client";

import { notify } from "@/lib/notify";
import { createClient } from "@/lib/supabase/client";
import { Database } from "@/lib/supabase/types";
import { PUBLIC_ROUTES } from "@/middleware/config";
import { Session } from "@supabase/supabase-js";
import { usePathname, useRouter } from "next/navigation";
import {
  createContext,
  ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

type Profile = Database["public"]["Tables"]["profiles"]["Row"];

interface ProfileContextType {
  profile: Profile | null;
  loading: boolean;
  logout: (redirectTo?: string | null) => Promise<void>;
  sync: () => Promise<void>;
}

const ProfileContext = createContext<ProfileContextType | undefined>(undefined);

function shouldStayOnSignOut(path: string | null): boolean {
  if (!path) return false;
  return PUBLIC_ROUTES.some((p) => path === p || path.startsWith(`${p}/`));
}

export function ProfileProvider({ children }: { children: ReactNode }) {
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);

  const lastFetchedUserIdRef = useRef<string | null>(null);
  const profileRef = useRef<Profile | null>(null);

  const supabase = useMemo(() => createClient(), []);
  const router = useRouter();
  const pathname = usePathname();

  useEffect(() => {
    profileRef.current = profile;
  }, [profile]);

  const fetchProfileByUserId = useCallback(
    async (userId: string) => {
      if (lastFetchedUserIdRef.current === userId && profileRef.current) {
        return;
      }

      lastFetchedUserIdRef.current = userId;

      const { data, error } = await supabase
        .from("profiles")
        .select("*")
        .eq("id", userId)
        .single();

      if (error) {
        lastFetchedUserIdRef.current = null;
        throw error;
      }

      setProfile(data);
    },
    [supabase],
  );

  const syncFromSession = useCallback(
    async (session: Session | null) => {
      setLoading(true);

      try {
        if (!session?.user) {
          lastFetchedUserIdRef.current = null;
          setProfile(null);
          return;
        }

        await fetchProfileByUserId(session.user.id);
      } catch {
        lastFetchedUserIdRef.current = null;
        setProfile(null);
      } finally {
        setLoading(false);
      }
    },
    [fetchProfileByUserId],
  );

  const sync = useCallback(async () => {
    setLoading(true);

    try {
      const {
        data: { user },
        error,
      } = await supabase.auth.getUser();

      if (error) throw error;

      if (!user) {
        lastFetchedUserIdRef.current = null;
        setProfile(null);
        return;
      }

      lastFetchedUserIdRef.current = null;
      await fetchProfileByUserId(user.id);
    } catch {
      lastFetchedUserIdRef.current = null;
      setProfile(null);
    } finally {
      setLoading(false);
    }
  }, [supabase, fetchProfileByUserId]);

  const logout = useCallback(
    async (redirectTo?: string | null) => {
      setLoading(true);

      try {
        const { error } = await supabase.auth.signOut();

        if (error) throw error;

        lastFetchedUserIdRef.current = null;
        setProfile(null);

        if (redirectTo === null) {
          router.refresh();
        } else {
          const target =
            redirectTo ??
            (shouldStayOnSignOut(pathname) ? pathname : "/sign-in");
          router.push(target ?? "/sign-in");
          router.refresh();
        }
      } catch {
        notify.error("Couldn't sign out", {
          description: "Please try again.",
        });
      } finally {
        setLoading(false);
      }
    },
    [supabase, router, pathname],
  );

  useEffect(() => {
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      if (
        event === "INITIAL_SESSION" ||
        event === "SIGNED_IN" ||
        event === "USER_UPDATED" ||
        event === "TOKEN_REFRESHED"
      ) {
        void syncFromSession(session);
      }

      if (event === "SIGNED_OUT") {
        lastFetchedUserIdRef.current = null;
        setProfile(null);
        setLoading(false);
        if (!shouldStayOnSignOut(pathname)) {
          router.push("/sign-in");
        }
        router.refresh();
      }
    });

    return () => subscription.unsubscribe();
  }, [supabase, syncFromSession, router, pathname]);

  return (
    <ProfileContext.Provider value={{ profile, loading, logout, sync }}>
      {children}
    </ProfileContext.Provider>
  );
}

export function useProfile() {
  const context = useContext(ProfileContext);

  if (context === undefined) {
    throw new Error("useProfile must be used within a ProfileProvider");
  }

  return context;
}

