import { createClient } from "@/lib/supabase/server";

export type SchoolOverviewData = {
  memberCount: number;
  pendingCount: number;
  principalName: string | null;
  createdAt: string | null;
};

export async function getSchoolOverviewData(
  schoolId: string,
): Promise<SchoolOverviewData> {
  const supabase = await createClient();

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    throw new Error("unauthenticated");
  }

  const [membersRes, pendingRes, principalRes, schoolRes] = await Promise.all([
    supabase
      .from("profiles")
      .select("id", { count: "exact", head: true })
      .eq("school_id", schoolId)
      .not("role", "is", null),
    supabase
      .from("invitations")
      .select("id", { count: "exact", head: true })
      .eq("school_id", schoolId)
      .eq("status", "pending"),
    supabase
      .from("profiles")
      .select("display_name")
      .eq("school_id", schoolId)
      .eq("role", "principal")
      .maybeSingle(),
    supabase
      .from("schools")
      .select("created_at")
      .eq("id", schoolId)
      .maybeSingle(),
  ]);

  return {
    memberCount: membersRes.count ?? 0,
    pendingCount: pendingRes.count ?? 0,
    principalName: principalRes.data?.display_name ?? null,
    createdAt: schoolRes.data?.created_at ?? null,
  };
}

