import { NotifyProvider } from "@/components/notify/notify-provider";
import { TooltipProvider } from "@/components/ui/tooltip";
import { NotificationsProvider } from "@/features/notifications";
import { getNotificationFeed } from "@/features/notifications/server";
import { ReactNode } from "react";
import { DashboardShell } from "./_components/dashboard-shell";
import { getUserProfileServer } from "./school/_queries";

export default async function DashboardLayout({
  children,
}: {
  children: ReactNode;
}) {
  const [{ user, profile }, feed] = await Promise.all([
    getUserProfileServer(),
    getNotificationFeed(),
  ]);

  return (
    <TooltipProvider>
      <NotificationsProvider
        userId={user?.id ?? null}
        initialNotifications={feed.notifications}
        initialUnreadCount={feed.unreadCount}
      >
        <DashboardShell profile={profile}>{children}</DashboardShell>
      </NotificationsProvider>
      <NotifyProvider />
    </TooltipProvider>
  );
}

