            <div className="relative flex min-h-0 flex-1 overflow-hidden">
              <main className="min-h-0 flex-1 overflow-y-auto p-4 md:p-8 md:pt-6">
                <div className="container mx-auto w-full max-w-screen-2xl">
                  {children}
                </div>
              </main>

              <SagePanel />
              <SageFab />
            </div>
          </SidebarInset>
        </div>
      </SidebarProvider>
    </SageProvider>
  );
}

