          tone === "default" && "text-foreground",
        )}
      >
        {value}
      </span>
    </div>
  );
}

export function StatCardSkeleton() {
  return (
    <div className="flex flex-col gap-1.5 rounded-xl border border-border bg-card px-4 py-3.5">
      <div className="h-3 w-16 rounded-full bg-muted animate-pulse" />
      <div className="h-7 w-10 rounded-md bg-muted animate-pulse" />
    </div>
  );
}

