  1	import { createClient } from "@/lib/supabase/server";
  2	import {
  3	  DIMENSION_KEY_ORDER,
  4	  DIMENSION_LABELS,
  5	  type AnalyticsData,
  6	  type Classification,
  7	  type DimensionKey,
  8	  type DistributionSlice,
  9	  type TrendPoint,
 10	} from "../_lib/analytics-types";
 11	import { isAnalysisPayload, normalizeStatus, type AnalysisPayload } from "@/app/(dashboard)/lessons/[id]/_lib/analysis-types";
 12	
 13	export async function getAnalytics(): Promise<AnalyticsData> {
 14	  const supabase = await createClient();
 15	  const { data: { user }, error: authError } = await supabase.auth.getUser();
 16	  if (authError || !user) {
 17	    return emptyData();
 18	  }
 19	
 20	  const { data, error } = await supabase
 21	    .from("lessons")
 22	    .select(`
 23	      id,
 24	      title,
 25	      created_at,
 26	      lesson_analyses ( id, payload, created_at )
 27	    `)
 28	    .order("created_at", { referencedTable: "lesson_analyses", ascending: false })
 29	    .limit(1, { referencedTable: "lesson_analyses" });
 30	
 31	  if (error || !data) {
 32	    console.error("getAnalytics: supabase fetch error", error);
 33	    return emptyData();
 34	  }
 35	
 36	  const analysedLessons = data
 37	    .filter((l) => l.lesson_analyses && l.lesson_analyses.length > 0)
 38	    .map((l) => ({
 39	      id: l.id,
 40	      title: l.title ?? "Untitled",
 41	      date: l.created_at ?? new Date().toISOString(),
 42	      analysis: l.lesson_analyses[0],
 43	    }));
 44	
 45	  if (analysedLessons.length === 0) {
 46	    return emptyData();
 47	  }
 48	
 49	  const payloads: { lessonId: string; title: string; date: string; payload: AnalysisPayload }[] = [];
 50	  for (const lesson of analysedLessons) {
 51	    const raw = lesson.analysis.payload;
 52	    if (isAnalysisPayload(raw)) {
 53	      payloads.push({
 54	        lessonId: lesson.id,
 55	        title: lesson.title,
 56	        date: lesson.date,
 57	        payload: raw,
 58	      });
 59	    }
 60	  }
 61	
 62	  if (payloads.length === 0) {
 63	    return emptyData();
 64	  }
 65	
 66	  const totalLessons = payloads.length;
 67	  const scores = payloads.map((p) => p.payload.overall_score);
 68	  const averageScore = round1(toPct(scores.reduce((a, b) => a + b, 0) / scores.length));
 69	
 70	  const classificationCounts: Record<Classification, number> = {
 71	    excellent: 0,
 72	    good: 0,
 73	    satisfactory: 0,
 74	    needs_improvement: 0,
 75	  };
 76	  for (const p of payloads) {
 77	    const status = normalizeStatus(p.payload.classification);
 78	    classificationCounts[status]++;
 79	  }
 80	  const topRatedCount = classificationCounts.excellent + classificationCounts.good;
 81	
 82	  const distribution: DistributionSlice[] = (
