import "server-only";

import { createClient } from "@/lib/supabase/server";
import { isAnalysisPayload } from "@/app/(dashboard)/lessons/[id]/_lib/analysis-types";
import { TeacherAnalytics } from "../_lib/types";

const DIMENSION_LABELS: Record<string, string> = {
  lesson_structure: "Lesson Structure",
  behaviour_management: "Behaviour Management",
  clarity: "Clarity",
  formative_assessment: "Formative Assessment",
  engagement: "Engagement",
  technology: "Technology",
};

const DIMENSION_WEIGHTS: Record<string, number> = {
  lesson_structure: 0.15,
  behaviour_management: 0.25,
  clarity: 0.20,
  formative_assessment: 0.15,
  engagement: 0.15,
  technology: 0.10,
};

export async function getTeacherAnalytics(
  teacherId: string,
): Promise<TeacherAnalytics> {
  const supabase = await createClient();

  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser();

  if (authError || !user) return null;

  const { data: latestLesson } = await supabase
    .from("lessons")
    .select("id, title")
    .eq("uploaded_by", teacherId)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (!latestLesson) return null;

  const { data: analysis } = await supabase
    .from("lesson_analyses")
    .select("payload, created_at")
    .eq("lesson_id", latestLesson.id)
    .eq("kind", "full_analysis")
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (!analysis?.payload || !isAnalysisPayload(analysis.payload)) {
    return null;
  }

  const payload = analysis.payload;

  const dimension_scores = payload.metrics.map((m) => ({
    key: m.name,
    label: DIMENSION_LABELS[m.name] ?? m.label,
    score: Math.round(m.score),
    weight: Math.round((DIMENSION_WEIGHTS[m.name] ?? 0.15) * 100),
  }));

  return {
    overall_score: Math.round(payload.overall_score),
    classification: payload.classification,
    dimension_scores,
    latest_lesson_title: latestLesson.title,
    latest_lesson_id: latestLesson.id,
    analyzed_at: analysis.created_at,
  };
}

