import { createClient } from "@/lib/supabase/server";
import { getUserProfileServer } from "../../school/_queries";
import { OrgSnapshot, OrgSummary, SchoolListItem } from "../_lib/types";

export async function getOrgSnapshot(): Promise<OrgSnapshot | null> {
  const { user, profile } = await getUserProfileServer();
  if (!user || !profile) return null;
  if (profile.role !== "org_admin" || !profile.organization_id) return null;

  const supabase = await createClient();
  const orgId = profile.organization_id;

  const [summaryResult, schoolsResult] = await Promise.all([
    supabase
      .rpc("get_organization_summary", { p_org_id: orgId })
      .single<OrgSummary>(),
    supabase
      .rpc("get_organization_schools", { p_org_id: orgId })
      .returns<SchoolListItem[]>(),
  ]);

  if (summaryResult.error) {
    console.error("[getOrgSnapshot] get_organization_summary failed", {
      error: summaryResult.error,
      orgId,
      userId: user.id,
    });
    return null;
  }

  if (schoolsResult.error) {
    console.error("[getOrgSnapshot] get_organization_schools failed", {
      error: schoolsResult.error,
      orgId,
      userId: user.id,
    });
    // We can still return summary if schools fail, or fail entirely. Let's fail entirely.
    return null;
  }

  return {
    organizationId: orgId,
    summary: summaryResult.data,
    schools: schoolsResult.data ?? [],
  };
}

