"use client";

import { Button } from "@/components/ui/button";
import { useI18n } from "@/i18n/client-provider";
import { PlusIcon } from "@phosphor-icons/react";
import { useMemo, useState } from "react";
import { useOrganization } from "../_hooks/use-organization";
import { OrgSnapshot } from "../_lib/types";
import { AddSchoolDialog } from "./add-school-dialog";
import { EmptyFiltered, EmptySchools } from "./empty-states";
import { SchoolCard } from "./school-card";
import { SchoolsToolbar } from "./schools-toolbar";
import { StatCard } from "./stat-card";

type Props = {
  snapshot: OrgSnapshot;
};

export function OrganizationShell({ snapshot }: Props) {
  const t = useI18n();
  const copy = t.dashboard.organization;

  const messages = useMemo(
    () => ({
      school_created: copy.toasts.school_created,
      generic_error: copy.errors.internal_error,
    }),
    [copy],
  );

  const o = useOrganization(snapshot, messages);
  const [addOpen, setAddOpen] = useState(false);

  const hasSchools = o.schools.length > 0;
  const hasResults = o.filteredSchools.length > 0;

  return (
    <div className="flex flex-col gap-6 p-4 md:p-6">
      <header className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex flex-col gap-0.5">
          <p className="text-[11px] font-semibold uppercase tracking-widest text-muted-foreground">
            {copy.page.eyebrow}
          </p>
          <h1 className="text-[22px] font-semibold tracking-tight text-foreground">
            {o.summary.name}
          </h1>
        </div>

        <Button
          type="button"
          size="sm"
          onClick={() => setAddOpen(true)}
          className="w-full sm:w-auto"
        >
          <PlusIcon size={13} weight="bold" />
          {copy.actions.add_school}
        </Button>
      </header>

      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <StatCard label={copy.stats.schools} value={o.summary.schools_count} />
        <StatCard label={copy.stats.members} value={o.summary.total_members} />
        <StatCard label={copy.stats.pending} value={o.summary.total_pending} />
        <StatCard
          label={copy.stats.no_principal}
          value={o.summary.schools_no_principal}
          tone={o.summary.schools_no_principal > 0 ? "warning" : "default"}
        />
      </div>

      {hasSchools && (
        <SchoolsToolbar filters={o.filters} onFilterChange={o.setFilter} />
      )}

      {!hasSchools && <EmptySchools onAddSchool={() => setAddOpen(true)} />}

      {hasSchools && !hasResults && o.hasActiveFilters && (
        <EmptyFiltered onClear={o.clearFilters} />
      )}

      {hasResults && (
        <div className="flex flex-col gap-2">
          <p className="text-[11px] font-medium text-muted-foreground">
            {o.filteredSchools.length === o.schools.length
              ? copy.schools_count.replace("{count}", String(o.schools.length))
              : copy.schools_filtered
                  .replace("{filtered}", String(o.filteredSchools.length))
                  .replace("{total}", String(o.schools.length))}
          </p>
          <div className="flex flex-col gap-2">
            {o.filteredSchools.map((school) => (
              <SchoolCard key={school.id} school={school} />
            ))}
          </div>
        </div>
      )}

      <AddSchoolDialog
        open={addOpen}
        onClose={() => setAddOpen(false)}
        onSubmit={o.addSchool}
