import { createClient } from "@/lib/supabase/server";
import { notFound } from "next/navigation";
import { searchParamsToFilters } from "./_lib/filter-types";
import { StaffShell } from "./_components/staff-shell";
import { TeacherGoalsShell } from "./_components/teacher-goals-shell";
import { getFilteredActionPlans } from "./_queries/get-action-plans-list";
import { getTeacherActionPlans } from "./_queries/get-teacher-action-plans";
import { getTeacherAnalytics } from "./_queries/get-teacher-analytics";

export const dynamic = "force-dynamic";

type Props = {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
};

export default async function Page({ searchParams }: Props) {
  const supabase = await createClient();
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser();

  if (authError || !user) notFound();

  const { data: profile } = await supabase
    .from("profiles")
    .select("id, role, school_id, organization_id")
    .eq("id", user.id)
    .single();

  if (!profile?.role) notFound();

  const isTeacher = profile.role === "teacher";

  if (isTeacher) {
    const [plans, analytics] = await Promise.all([
      getTeacherActionPlans(user.id),
      getTeacherAnalytics(user.id),
