"use client";

import { useCallback, useOptimistic, useState, useTransition } from "react";
import { useI18n } from "@/i18n/client-provider";
import { notify } from "@/lib/notify";
import {
  CaretDownIcon,
  CaretUpIcon,
  CheckCircleIcon,
  ClockIcon,
  PlusIcon,
  SparkleIcon,
} from "@phosphor-icons/react";
import { checkGoalProgressAction } from "../_actions/check-goal-progress-action";
import { deleteActionPlanAction } from "../_actions/delete-action-plan-action";
import {
  ActionPlanRow,
  GoalProgress,
  TeacherAnalytics,
} from "../_lib/types";
import { GoalCard } from "./goal-card";
import { GoalFormInline } from "./goal-form-inline";
import { EditGoalDialog } from "./edit-goal-dialog";
import { ProgressReveal } from "./progress-reveal";
import { TeacherAnalyticsPanel } from "./teacher-analytics-panel";

type Props = {
  actionPlans: ActionPlanRow[];
  teacherId: string;
  analytics: TeacherAnalytics;
};

export function TeacherGoalsShell({
  actionPlans,
  teacherId,
  analytics,
}: Props) {
  const t = useI18n();
  const copy = t.dashboard.actionPlans;

  const [plans, setPlans] = useState(actionPlans);
  const [optimisticPlans, addOptimisticPlan] = useOptimistic(
    plans,
    (state, planId: string) => state.filter((p) => p.id !== planId),
  );

  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [editingPlan, setEditingPlan] = useState<ActionPlanRow | null>(null);
  const [showCompleted, setShowCompleted] = useState(false);
  const [showForm, setShowForm] = useState(false);

  const [checkingProgressId, setCheckingProgressId] = useState<string | null>(
    null,
  );
  const [progressMap, setProgressMap] = useState<Record<string, GoalProgress>>(
    {},
  );

  const [, startTransition] = useTransition();

import { StatCardSkeleton } from "../../_components/stat-card";

export default function SchoolOverviewLoading() {
  return (
    <div className="flex flex-col gap-6 p-4 md:p-6">
      <div className="flex items-start gap-4">
        <div className="size-12 shrink-0 rounded-lg bg-muted animate-pulse" />
        <div className="flex flex-col gap-1.5">
          <div className="h-5 w-40 rounded-md bg-muted animate-pulse" />
          <div className="h-3.5 w-20 rounded-full bg-muted/60 animate-pulse" />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
        {Array.from({ length: 3 }).map((_, i) => (
          <StatCardSkeleton key={i} />
        ))}
      </div>

      <div className="h-24 w-full rounded-xl border border-border bg-muted/20 animate-pulse" />
    </div>
  );
}

