const activeGoals = optimisticPlans.filter(
  (p) => p.status === "Active" || p.status === "Pending",
);
const metGoals = optimisticPlans.filter((p) => p.status === "Met");

const handlePlanCompleted = useCallback((planId: string) => {
  setPlans((prev) =>
    prev.map((p) =>
      p.id === planId ? { ...p, status: "Met" as const } : p,
    ),
  );
  setProgressMap((prev) => {
    const next = { ...prev };
    delete next[planId];
    return next;
  });
}, []);

const handleDelete = useCallback(
  async (planId: string) => {
    setDeletingId(planId);
    startTransition(() => {
      addOptimisticPlan(planId);
    });

    try {
      const r = await deleteActionPlanAction(planId);
      if (r.success) {
        notify.success(r.message ?? copy.delete.deleted);
        setPlans((prev) => prev.filter((p) => p.id !== planId));
      } else {
        notify.error(r.message ?? copy.delete.delete_failed);
        setPlans((prev) => prev);
      }
    } catch {
      notify.error(copy.delete.delete_failed);
      setPlans((prev) => prev);
    } finally {
      setDeletingId(null);
    }
  },
  [copy, addOptimisticPlan, startTransition],
);

const handlePlanAdded = useCallback((plan: ActionPlanRow) => {
  setPlans((prev) => [plan, ...prev]);
}, []);

const handlePlanUpdated = useCallback((plan: ActionPlanRow) => {
  setPlans((prev) =>
    prev.map((p) => (p.id === plan.id ? { ...p, ...plan } : p)),
  );
}, []);

const handleCheckProgress = useCallback(
  async (planId: string) => {
    if (progressMap[planId]) {
      setProgressMap((prev) => {
        const next = { ...prev };
        delete next[planId];
        return next;
      });
      return;
    }

    setCheckingProgressId(planId);
    try {
      const r = await checkGoalProgressAction(planId);
      if (r.success && r.data) {
        setProgressMap((prev) => ({ ...prev, [planId]: r.data! }));
      } else {
        notify.error(r.message ?? copy.progress.failed);
      }
    } catch {
      notify.error(copy.progress.failed);
    } finally {
      setCheckingProgressId(null);
    }
  },

  [progressMap, copy],
);

return (
  <>
    <div className="flex flex-col gap-6 p-4 md:gap-8 md:p-8 lg:flex-row lg:gap-8">
      <div className="flex min-w-0 flex-1 flex-col gap-8">
        <div className="flex items-end justify-between gap-4">
          <div className="flex flex-col gap-2">
            <h1 className="text-lg font-bold tracking-tight text-foreground">
              {copy.headings.my_goals}
            </h1>
            <p className="text-[13px] leading-relaxed text-muted-foreground">
              Based on your lesson analysis, identify an area to{" "}
              <span className="font-semibold text-foreground">focus on</span>{" "}
              for improvement. Set a clear, actionable goal to work towards.
            </p>
          </div>

          {!showForm && (
            <button
              type="button"
              onClick={() => setShowForm(true)}
              className="inline-flex shrink-0 items-center gap-2 rounded-xl bg-primary px-5 py-2.5 text-[14px] font-medium text-primary-foreground transition-all duration-200 hover:bg-primary/90 active:scale-95"
            >
              <PlusIcon size={16} weight="bold" />
              New
            </button>
          )}
        </div>

        {showForm && (
          <GoalFormInline
            teacherId={teacherId}
            onSaved={handlePlanAdded}
            onClose={() => setShowForm(false)}
          />
        )}

        {activeGoals.length === 0 && metGoals.length === 0 && !showForm && (
          <div className="flex flex-col items-center gap-4 rounded-2xl border-2 border-dashed border-primary/20 bg-primary/[0.02] px-6 py-12 text-center">
            <div className="flex size-12 items-center justify-center rounded-full bg-primary/10">
              <SparkleIcon size={22} weight="duotone" className="text-primary" />
            </div>
            <div className="flex flex-col gap-1">
              <p className="text-[14px] font-medium text-foreground">
                {copy.empty_teacher.title}
              </p>
              <p className="max-w-xs text-[13px] leading-relaxed text-muted-foreground">
                {copy.empty_teacher.description}
              </p>
            </div>
          </div>
        )}

        {activeGoals.length > 0 && (
          <section className="flex flex-col gap-6">
            <div className="flex items-center gap-2">
              <ClockIcon size={14} weight="fill" className="text-primary" />
              <h2 className="text-[13px] font-semibold uppercase tracking-wider text-muted-foreground">
                {copy.sections.active}
              </h2>
              <span className="text-[11px] text-muted-foreground">
                ({activeGoals.length})
              </span>
            </div>

            <div className="flex flex-col gap-8">
              {activeGoals.map((plan) => (
                <div key={plan.id} className="flex flex-col gap-4">
                  <GoalCard
                    plan={plan}
                    copy={copy}
                    onEdit={setEditingPlan}
                    onDelete={handleDelete}
                    deleting={deletingId === plan.id}
