                  <div className="pl-0">
                    <button
                      type="button"
                      onClick={() => handleCheckProgress(plan.id)}
                      disabled={checkingProgressId === plan.id}
                      className="inline-flex items-center gap-2 rounded-lg border border-primary/20 bg-primary/5 px-4 py-2 text-[12px] font-medium text-primary transition-all duration-200 hover:bg-primary/10 disabled:opacity-50"
