import "server-only";

import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { Resend } from "resend";

const EMAILS_DIR = join(process.cwd(), "emails");

const FROM_ADDRESS = "Learnalyze <noreply@learnalyze.app>";

type TemplateVars = Record<string, string>;

async function loadTemplate(name: string): Promise<string> {
  const path = join(EMAILS_DIR, `${name}.html`);
  return readFile(path, "utf-8");
}

function render(template: string, vars: TemplateVars): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => vars[key] ?? "");
}

let _resend: Resend | null = null;

function getResend(): Resend {
  if (!_resend) {
    const apiKey = process.env.RESEND_API_KEY;
    if (!apiKey) {
      throw new Error("RESEND_API_KEY is not set");
    }
    _resend = new Resend(apiKey);
  }
  return _resend;
}

export type SendEmailArgs = {
  to: string;
  subject: string;
  templateName: string;
  vars: TemplateVars;
};

export async function sendEmail({
  to,
  subject,
  templateName,
  vars,
}: SendEmailArgs): Promise<{ ok: boolean; error?: string }> {
  try {
    const template = await loadTemplate(templateName);
    const html = render(template, vars);
    const resend = getResend();

    const { error } = await resend.emails.send({
      from: FROM_ADDRESS,
      to: [to],
      subject,
      html,
    });

    if (error) {
      console.error("sendEmail failed:", { to, subject, error: error.message });
      return { ok: false, error: error.message };
    }

    return { ok: true };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.error("sendEmail error:", { to, subject, error: message });
    return { ok: false, error: message };
  }
}

