"use server";

import { getT } from "@/i18n/server";
import { createClient } from "@/lib/supabase/server";
import { ActionStateResponse } from "@/types/actions";
import { z } from "zod";
import { getForgotPasswordSchema } from "../_lib/auth-schema";

export async function forgotPasswordAction(
  _prevState: ActionStateResponse<null>,
  formData: FormData,
): Promise<ActionStateResponse<null>> {
  const t = await getT();
  const supabase = await createClient();

  const values = Object.fromEntries(formData.entries());
  const validate = getForgotPasswordSchema(t).safeParse(values);

  if (!validate.success) {
    return {
      success: false,
      message: "",
      errors: z.flattenError(validate.error).fieldErrors,
    };
  }

  try {
    const { error } = await supabase.auth.resetPasswordForEmail(
      validate.data.email,
      {
        redirectTo: `${process.env.NEXT_PUBLIC_SITE_URL}/reset-password`,
      },
    );

    if (error) {
      console.error("Forgot Password Auth Error:", { action: "forgotPasswordAction", error });

      let message = t.auth.forgotPassword.error.internal_error;
      const lowerError = error.message.toLowerCase();

      if (lowerError.includes("rate limit") || lowerError.includes("too many requests")) {
         message = t.auth.forgotPassword.error.too_many_requests;
      } else if (lowerError.includes("user not found")) {
        // Obfuscate for security to not leak registered emails, return success message or general generic.
        message = t.auth.forgotPassword.error.user_not_found;
      }

      return {
        success: false,
        message,
      };
    }
  } catch (error) {
    console.error("Forgot Password Exception:", { action: "forgotPasswordAction", error });
    return {
      success: false,
      message: t.auth.forgotPassword.error.internal_error,
    };
  }

  return {
    success: true,
    message: t.auth.forgotPassword.success_message,
  };
}

