  const lessonLink = `${siteUrl}/lessons/${lesson_id}`;

  void pushNotification({
    userId: lesson.uploaded_by,
    kind: "analysis_complete",
    tone: "success",
    title: "Analysis complete",
    subtitle: lessonTitle,
    bodyMd: "Your lesson analysis is ready to view.",
    link: `/lessons/${lesson_id}`,
  });

  const { data: teacher } = await supabase
    .from("profiles")
    .select("email, display_name")
    .eq("id", lesson.uploaded_by)
    .maybeSingle();

  if (teacher?.email) {
    void email
      .sendAnalysisComplete({
        to: teacher.email,
        teacherName: teacher.display_name ?? teacher.email,
        lessonTitle,
        lessonLink,
      })
      .then((result) => {
        if (!result.ok) {
          console.error("analysis-complete webhook: email failed", {
            lessonId: lesson_id,
            teacherEmail: teacher.email,
            error: result.error,
          });
        }
      });
  }
}

return Response.json({ ok: true, data: { lesson_id, status } });

