import "server-only";

import { FROM, getResend } from "./_lib/client";
import {
  type ActionPlanReminderEmailArgs,
  buildActionPlanReminderEmail,
} from "./_templates/action-plan-reminder";
import {
  type AnalysisCompleteEmailArgs,
  buildAnalysisCompleteEmail,
} from "./_templates/analysis-complete";
import {
  type InvitationEmailArgs,
  buildInvitationEmail,
} from "./_templates/invitation";
import {
  type PasswordResetEmailArgs,
  buildPasswordResetEmail,
} from "./_templates/password-reset";
import { type WelcomeEmailArgs, buildWelcomeEmail } from "./_templates/welcome";

export type EmailResult = { ok: true } | { ok: false; error: string };

async function send(to: string, subject: string, html: string): Promise<EmailResult> {
  try {
    const { error } = await getResend().emails.send({
      from: FROM,
      to: [to],
      subject,
      html,
    });

    if (error) {
      console.error("email.send failed", { to, subject, error: error.message });
      return { ok: false, error: error.message };
    }

    return { ok: true };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.error("email.send threw", { to, subject, error: message });
    return { ok: false, error: message };
  }
}

export const email = {
  async sendInvitation(args: InvitationEmailArgs): Promise<EmailResult> {
    const { subject, html } = await buildInvitationEmail(args);
    return send(args.to, subject, html);
  },

  async sendAnalysisComplete(args: AnalysisCompleteEmailArgs): Promise<EmailResult> {
    const { subject, html } = await buildAnalysisCompleteEmail(args);
    return send(args.to, subject, html);
  },

  async sendPasswordReset(args: PasswordResetEmailArgs): Promise<EmailResult> {
    const { subject, html } = await buildPasswordResetEmail(args);
    return send(args.to, subject, html);
  },

  async sendWelcome(args: WelcomeEmailArgs): Promise<EmailResult> {
    const { subject, html } = await buildWelcomeEmail(args);
    return send(args.to, subject, html);
  },

  async sendActionPlanReminder(
    args: ActionPlanReminderEmailArgs,
  ): Promise<EmailResult> {
    const { subject, html } = await buildActionPlanReminderEmail(args);
    return send(args.to, subject, html);
  },
} as const;

export type {
  InvitationEmailArgs,
  AnalysisCompleteEmailArgs,
  PasswordResetEmailArgs,
  WelcomeEmailArgs,
  ActionPlanReminderEmailArgs,
};

