import { notFound } from "next/navigation";
import { ReactNode } from "react";
import { getOrgSchoolMeta } from "../_queries/get-org-school-meta";
import { SchoolBreadcrumb } from "./_components/school-breadcrumb";

type Props = {
  children: ReactNode;
  params: Promise<{ schoolId: string }>;
};

export default async function OrgSchoolLayout({ children, params }: Props) {
  const { schoolId } = await params;
  const result = await getOrgSchoolMeta(schoolId);
  if (!result.ok) notFound();

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <SchoolBreadcrumb school={result.school} />
      {children}
    </div>
  );
}

