"use client";

import { useI18n } from "@/i18n/client-provider";
import { Button } from "@/components/ui/button";
import { PlayCircleIcon } from "@phosphor-icons/react";
import Link from "next/link";
import type { AnalyticsData } from "../_lib/analytics-types";
import { kpiPrompt, dimensionsPrompt, distributionPrompt, trendPrompt } from "../_lib/sage-prompts";
import { SageHoverAction } from "./sage-hover-action";
import { KpiStrip } from "./kpi-strip";
import { DimensionsChart } from "./dimensions-chart";
import { DistributionChart } from "./distribution-chart";
import { TrendChart } from "./trend-chart";

type Props = {
  data: AnalyticsData;
};

export function AnalyticsShell({ data }: Props) {
  const t = useI18n();
  const copy = t.dashboard.analytics;

  if (data.isEmpty) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 px-6 py-24 text-center">
        <div className="flex size-12 items-center justify-center rounded-full bg-muted text-muted-foreground ring-1 ring-border">
          <PlayCircleIcon size={24} />
        </div>
        <h3 className="text-[15px] font-medium text-foreground">
          {copy.empty_title}
        </h3>
        <p className="max-w-[400px] text-[13px] leading-relaxed text-muted-foreground">
          {copy.empty_body}
        </p>
        <Button asChild variant="outline" size="sm" className="mt-2">
          <Link href="/lessons/upload">{copy.empty_cta}</Link>
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <SageHoverAction prompt={kpiPrompt(data)} className="pb-1">
        <KpiStrip kpis={data.kpis} />
      </SageHoverAction>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <SageHoverAction prompt={dimensionsPrompt(data)}>
          <div className="rounded-lg border bg-card p-4 sm:p-5">
            <h2 className="text-base font-medium tracking-tight">{copy.dimensions_title}</h2>
            <p className="text-xs text-muted-foreground mt-0.5 mb-3">{copy.dimensions_desc}</p>
            <DimensionsChart
              dimensions={data.dimensions}
              overallScore={data.overallScore}
              primaryFocusKey={data.kpis.primaryFocus.key}
              totalLessons={data.kpis.totalLessons}
            />
          </div>
        </SageHoverAction>

        <SageHoverAction prompt={distributionPrompt(data)}>
          <div className="rounded-lg border bg-card p-4 sm:p-5">
            <h2 className="text-base font-medium tracking-tight">{copy.distribution_title}</h2>
            <p className="text-xs text-muted-foreground mt-0.5 mb-3">{copy.distribution_desc}</p>
            <DistributionChart
              distribution={data.distribution}
              totalLessons={data.kpis.totalLessons}
            />
          </div>
        </SageHoverAction>
      </div>

      <SageHoverAction prompt={trendPrompt(data)}>
        <div className="rounded-lg border bg-card p-4 sm:p-5">
          <h2 className="text-base font-medium tracking-tight">{copy.trend_title}</h2>
          <p className="text-xs text-muted-foreground mt-0.5 mb-3">{copy.trend_desc}</p>
          <TrendChart trend={data.trend} averageScore={data.kpis.averageScore} />
        </div>
      </SageHoverAction>
    </div>
  );
}

