import { notFound, redirect } from "next/navigation";
import { getInviters, getSchoolStaffData, getUserProfile } from "../_queries";
import { StaffShell } from "./_components/staff-shell";
import {
  Invitation,
  InvitationStatus,
  Member,
  Role,
  StaffSnapshot,
} from "./_lib/types";

type StaffRow = {
  id: string;
  email: string;
  display_name: string | null;
  avatar_url: string | null;
  role: Role | null;
  department_id: string | null;
  subject_id: string | null;
  phase_id: string | null;
  last_sign_in_at: string | null;
};

type Lookup = Record<string, string>;

function nameFromEmail(email: string): string {
  const local = email.split("@")[0] ?? email;
  return local.charAt(0).toUpperCase() + local.slice(1);
}

export default async function StaffPage() {
  const { user, profile } = await getUserProfile();

  if (!user) redirect("/sign-in");
  if (!profile?.school_id || !profile.role) notFound();

  if (profile.role !== "principal" && profile.role !== "org_admin") {
    redirect("/forbidden");
  }

  const schoolId = profile.school_id as string;
  const inviterRole = profile.role as Role;

  const data = await getSchoolStaffData(schoolId);

  const staff = data.staff as StaffRow[];
  const departments: Lookup = Object.fromEntries(
    data.departments.map((d: { id: string; name: string }) => [d.id, d.name]),
  );
  const subjects: Lookup = Object.fromEntries(
    data.subjects.map((s: { id: string; name: string }) => [s.id, s.name]),
  );
  const phases: Lookup = Object.fromEntries(
    data.phases.map((p: { id: string; name: string }) => [p.id, p.name]),
  );
  const grades: Lookup = Object.fromEntries(
    data.grades.map((g: { id: string; name: string }) => [g.id, g.name]),
  );

  const profileGrades = new Map<string, string[]>();
  for (const tg of data.teacherGrades) {
    const profileId = tg.profile_id as string;
    const gradeId = tg.grade_id as string;
    const gradeName = grades[gradeId];
    if (!gradeName) continue;
    const list = profileGrades.get(profileId) ?? [];
    list.push(gradeName);
    profileGrades.set(profileId, list);
  }

  const members: Member[] = staff
    .filter((s) => s.role !== null)
    .map((s) => ({
      id: s.id,
      display_name: s.display_name ?? nameFromEmail(s.email),
      email: s.email,
      avatar_url: s.avatar_url,
      role: s.role as Role,
      department: s.department_id
        ? (departments[s.department_id] ?? null)
        : null,
      subject: s.subject_id ? (subjects[s.subject_id] ?? null) : null,
      phase: s.phase_id ? (phases[s.phase_id] ?? null) : null,
      grades: profileGrades.get(s.id) ?? [],
      last_sign_in_at: s.last_sign_in_at,
    }));

  const inviterIds = Array.from(
    new Set(
      data.invitations
        .map((i: { invited_by: string | null }) => i.invited_by as string)
        .filter(Boolean),
    ),
  );

  const invitersData = await getInviters(inviterIds);

  const invitersById: Record<string, string> = Object.fromEntries(
    invitersData.map(
      (p: { id: string; display_name: string | null; email: string }) => [
        p.id,
        p.display_name ?? nameFromEmail(p.email),
      ],
    ),
  );

  const gradesByInvitation = new Map<string, string[]>();
  for (const ig of data.invitationGrades) {
    const list = gradesByInvitation.get(ig.invitation_id as string) ?? [];
    list.push(ig.grade_name as string);
    gradesByInvitation.set(ig.invitation_id as string, list);
  }

  const invitations: Invitation[] = data.invitations.map(
    (i: {
      id: string;
      email: string;
      role: string;
      token: string;
      department_name: string | null;
      subject_name: string | null;
      phase_name: string | null;
      invited_by: string;
      status: string;
      sent_at: string;
      expires_at: string;
      resent_count: number;
      last_resent_at: string | null;
      import_batch_id: string | null;
    }) => ({
      id: i.id as string,
      email: i.email as string,
      role: i.role as Role,
      token: i.token as string,
      department_name: i.department_name as string | null,
      subject_name: i.subject_name as string | null,
      phase_name: i.phase_name as string | null,
      grades: gradesByInvitation.get(i.id as string) ?? [],
      invited_by_name: invitersById[i.invited_by as string] ?? "—",
      status: i.status as InvitationStatus,
      sent_at: i.sent_at as string,
      expires_at: i.expires_at as string,
      resent_count: i.resent_count as number,
      last_resent_at: i.last_resent_at as string | null,
      import_batch_id: i.import_batch_id as string | null,
    }),
  );

  const snapshot: StaffSnapshot = {
    schoolId,
    inviterRole,
    members,
    invitations,
    allDepartments: Object.values(departments).sort(),
    allSubjects: Object.values(subjects).sort(),
    allPhases: Object.values(phases).sort(),
    allGrades: Object.values(grades).sort(),
  };

  return <StaffShell snapshot={snapshot} />;
}

