import { createClient } from "@/lib/supabase/server";
import { getUserProfileServer } from "../../school/_queries";
import { SchoolMeta } from "../_lib/types";

export type SchoolAccessResult =
  | { ok: true; school: SchoolMeta }
  | {
      ok: false;
      reason: "unauthenticated" | "not_org_admin" | "not_in_org" | "not_found";
    };

export async function getOrgSchoolMeta(
  schoolId: string,
): Promise<SchoolAccessResult> {
  const { user, profile } = await getUserProfileServer();
  if (!user || !profile) return { ok: false, reason: "unauthenticated" };
  if (profile.role !== "org_admin")
    return { ok: false, reason: "not_org_admin" };
  if (!profile.organization_id) return { ok: false, reason: "not_org_admin" };

  const supabase = await createClient();
  const { data, error } = await supabase
    .from("schools")
    .select("id, name, organization_id, country, logo_url")
    .eq("id", schoolId)
    .maybeSingle();

  if (error || !data) return { ok: false, reason: "not_found" };
  if (data.organization_id !== profile.organization_id)
    return { ok: false, reason: "not_in_org" };

  return {
    ok: true,
    school: {
      id: data.id,
      name: data.name,
      organization_id: data.organization_id,
      country: data.country,
      logo_url: data.logo_url,
    },
  };
}

