export type DimensionName =
  | "structure"
  | "management"
  | "clarity"
  | "assessment"
  | "engagement"
  | "technology";

/** JSON keys as they appear in metrics[].name */
export type MetricKey =
  | "lesson_structure"
  | "behaviour_management"
  | "clarity"
  | "formative_assessment"
  | "engagement"
  | "technology";

export type FactorType = "evidence" | "strength" | "improvement";

export type AnalysisStatus =
  | "excellent"
  | "good"
  | "satisfactory"
  | "needs_improvement";

export type AnalysisFactor = {
  type: FactorType;
  text: string;
  timestamp?: string;
  technique?: string;
};

export type AnalysisMetric = {
  name: MetricKey;
  score: number;
  label: string;
  narrative: string;
  factors: AnalysisFactor[];
};

