import { createClient } from "@/lib/supabase/server";
import type { AnalyticsSummary } from "../_lib/analytics-types";
import { regenerateAnalyticsSummary } from "../_actions/regenerate-analytics-summary";

export async function getAnalyticsSummary(): Promise<AnalyticsSummary | null> {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user) return null;

  const { data: analyses } = await supabase
    .from("lessons")
    .select(`id, lesson_analyses ( id, created_at )`)
    .order("created_at", {
      referencedTable: "lesson_analyses",
      ascending: false,
    })
    .limit(1, { referencedTable: "lesson_analyses" });

  const analysedIds = (analyses ?? [])
    .filter((l) => l.lesson_analyses && l.lesson_analyses.length > 0)
    .map((l) => l.lesson_analyses[0])
    .sort((a, b) => a.id.localeCompare(b.id));

  if (analysedIds.length < 3) return null;

  const fingerprint = analysedIds.map((a) => `${a.id}|${a.created_at}`).join("|");

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const db = supabase.from as any;

  const { data: row, error: rowError } = await db("analytics_summaries")
    .select("*")
    .eq("scope_type", "teacher")
    .eq("scope_id", user.id)
    .maybeSingle();

  if (rowError) {
    console.error("getAnalyticsSummary: fetch error", rowError);
    return null;
  }

  const stale = !row || row.source_fingerprint !== fingerprint;

  if (row) {
    if (stale) {
      regenerateAnalyticsSummary();
    }

    let strengths: string[] = [];
    let growthOpportunities: string[] = [];
    try {
      strengths =
        typeof row.strengths === "string"
          ? JSON.parse(row.strengths)
          : (row.strengths as string[]);
      growthOpportunities =
        typeof row.growth_opportunities === "string"
          ? JSON.parse(row.growth_opportunities)
          : (row.growth_opportunities as string[]);
    } catch {
      // keep empty arrays
    }

    return {
      strengths,
      growthOpportunities,
      generatedAt: row.generated_at as string,
      stale,
    };
  }

  const result = await regenerateAnalyticsSummary();
  if (!result.success) return null;

  const { data: freshRow } = await db("analytics_summaries")
    .select("*")
    .eq("scope_type", "teacher")
    .eq("scope_id", user.id)
    .maybeSingle();

  if (!freshRow) return null;

  let strengths: string[] = [];
  let growthOpportunities: string[] = [];
  try {
    strengths =
      typeof freshRow.strengths === "string"
        ? JSON.parse(freshRow.strengths)
        : (freshRow.strengths as string[]);
    growthOpportunities =
      typeof freshRow.growth_opportunities === "string"
        ? JSON.parse(freshRow.growth_opportunities)
        : (freshRow.growth_opportunities as string[]);
  } catch {
    // keep empty arrays
  }

  return {
    strengths,
    growthOpportunities,
    generatedAt: freshRow.generated_at as string,
    stale: false,
  };
}

"use client";

import { useI18n } from "@/i18n/client-provider";
import type { AnalyticsSummary } from "../_lib/analytics-types";
import { SageHoverAction } from "./sage-hover-action";
import { growthOpportunityPrompt } from "../_lib/sage-prompts";

type Props = {
  summary: AnalyticsSummary | null;
  totalLessons: number;
};

export function AiSummaryClient({ summary, totalLessons }: Props) {
  const t = useI18n();
  const copy = t.dashboard.analytics;

  if (!summary) {
    return (
      <div className="rounded-lg border bg-card p-5">
        <h2 className="text-base font-medium tracking-tight">{copy.partial_lock_title}</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          {copy.partial_lock_body.replace("{count}", String(totalLessons))}
        </p>
      </div>
    );
  }

  return (
    <div className="rounded-lg border bg-card p-5">
      <div className="flex items-center gap-2">
        <h2 className="text-base font-medium tracking-tight">{copy.ai_summary_title}</h2>
        {summary.stale && (
          <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
            Updating…
          </span>
        )}
      </div>

      <div className="mt-4 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div>
          <div className="flex items-center gap-2 mb-3">
            <div className="w-2 h-2 rounded-full bg-[var(--chart-1)]" />
            <h3 className="text-sm font-medium text-foreground">{copy.ai_strengths_heading}</h3>
          </div>
          <ul className="divide-y divide-border">
            {summary.strengths.map((s, i) => (
              <li key={`s-${i}`} className="py-3 first:pt-0 last:pb-0">
                <p className="text-[13px] leading-relaxed text-foreground/85">{s}</p>
              </li>
            ))}
          </ul>
        </div>

        <div>
          <div className="flex items-center gap-2 mb-3">
            <div className="w-2 h-2 rounded-full bg-[var(--chart-5)]" />
            <h3 className="text-sm font-medium text-foreground">{copy.ai_growth_heading}</h3>
          </div>
          <ul className="divide-y divide-border">
            {summary.growthOpportunities.map((g, i) => (
              <li key={`g-${i}`} className="py-3 first:pt-0 last:pb-0">
                <SageHoverAction prompt={growthOpportunityPrompt(g)}>
                  <p className="text-[13px] leading-relaxed text-foreground/85">{g}</p>
                </SageHoverAction>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}

