export function SageHoverAction({ prompt, children, className }: Props) {
  const sage = useSageContext();

  return (
    <div className={cn("relative group", className)}>
      {children}
      <button
        type="button"
        onClick={() => sage.openWithPrompt(prompt)}
        className={cn(
          "absolute bottom-3 right-3 z-10",
          "inline-flex items-center gap-1.5 rounded-full border bg-card px-3 h-7",
          "text-xs font-medium text-primary",
          "opacity-0 translate-y-1 group-hover:opacity-100 group-hover:translate-y-0",
          "group-focus-within:opacity-100 group-focus-within:translate-y-0",
          "transition-[opacity,transform] duration-100 ease-out",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1",
          "max-sm:opacity-100 max-sm:translate-y-0",
          "motion-reduce:transition-none motion-reduce:opacity-100 motion-reduce:translate-y-0",
        )}
      >
        <ChatCircleDots size={14} />
        Discuss with Sage
      </button>
    </div>
  );
}

