import "server-only";

import {
  isAnalysisPayload,
  normalizeStatus,
  type AnalysisPayload,
} from "@/app/(dashboard)/lessons/[id]/_lib/analysis-types";
import {
  DIMENSION_KEY_ORDER,
  DIMENSION_LABELS,
  type AnalyticsData,
  type Classification,
  type DimensionKey,
} from "@/app/(dashboard)/analytics/_lib/analytics-types";
import { createClient } from "@/lib/supabase/server";

export type TeacherStat = {
  id: string;
  name: string;
  email: string;
  avatarUrl: string | null;
  role: string;
  totalLessons: number;
  analysedLessons: number;
  averageScore: number | null;
  lowestDimension: string | null;
  lastAnalysedAt: string | null;
};

export type SchoolAnalyticsData = {
  aggregate: AnalyticsData;
  teachers: TeacherStat[];
  activeTeacherCount: number;
  isEmpty: boolean;
};

const KEY_MAP: Record<string, DimensionKey> = {
  lesson_structure: "lesson_structure",
  behaviour_management: "behaviour_management",
  clarity: "clarity",
  formative_assessment: "formative_assessment",
  engagement: "engagement",
  technology: "technology",
};

function toPct(v: number) {
  return Math.round(v * 100);
}

function avg(arr: number[]) {
  return arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;
}

function emptyAggregate(): AnalyticsData {
  return {
    kpis: {
      totalLessons: 0,
      averageScore: 0,
      topRatedCount: 0,
      primaryFocus: { key: "clarity", label: "Clarity", score: 0 },
    },
    dimensions: DIMENSION_KEY_ORDER.map((key) => ({
      key,
      label: DIMENSION_LABELS[key],
      score: 0,
    })),
    overallScore: 0,
    distribution: [],
    trend: [],
    isEmpty: true,
    hasSummaryData: false,
  };
}

export async function getSchoolAnalytics(
  schoolId: string,
): Promise<SchoolAnalyticsData | null> {
  const supabase = await createClient();

  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser();

  if (authError || !user) return null;

  const [profilesRes, lessonsRes] = await Promise.all([
    supabase
      .from("profiles")
      .select("id, display_name, email, avatar_url, role")
      .eq("school_id", schoolId)
      .in("role", ["teacher", "head_of_department"]),

    supabase
      .from("lessons")
      .select(
        "id, title, created_at, uploaded_by, lesson_analyses(id, payload, created_at)",
      )
      .eq("school_id", schoolId)
      .order("created_at", { referencedTable: "lesson_analyses", ascending: false })
      .limit(1, { referencedTable: "lesson_analyses" }),
  ]);

  if (lessonsRes.error) {
    console.error("getSchoolAnalytics: lessons fetch failed", {
      schoolId,
      error: lessonsRes.error,
    });
    return null;
  }

import { createClient } from "@/lib/supabase/server";

export async function getSchoolStaffData(schoolId: string) {
  const supabase = await createClient();

  const [
    staffResult,
    departmentsResult,
    subjectsResult,
    phasesResult,
    gradesResult,
    teacherGradesResult,
    invitationsResult,
    invitationGradesResult,
  ] = await Promise.all([
    supabase.rpc("get_school_staff", { p_school_id: schoolId }),
    supabase.from("departments").select("id, name").eq("school_id", schoolId),
    supabase
      .from("subjects")
      .select("id, name, departments!inner(school_id)")
      .eq("departments.school_id", schoolId),
    supabase.from("phases").select("id, name").eq("school_id", schoolId),
    supabase.from("grades").select("id, name").eq("school_id", schoolId),
    supabase.from("teacher_grades").select("profile_id, grade_id"),
    supabase
      .from("invitations")
      .select(
        "id, email, role, token, department_name, subject_name, phase_name, status, sent_at, expires_at, resent_count, last_resent_at, import_batch_id, invited_by",
      )
      .eq("school_id", schoolId)
      .in("status", ["pending", "expired"])
      .order("sent_at", { ascending: false }),
    supabase.from("invitation_grades").select("invitation_id, grade_name"),
  ]);

  return {
    staff: staffResult.data ?? [],
    departments: departmentsResult.data ?? [],
    subjects: subjectsResult.data ?? [],
    phases: phasesResult.data ?? [],
    grades: gradesResult.data ?? [],
    teacherGrades: teacherGradesResult.data ?? [],
    invitations: invitationsResult.data ?? [],
    invitationGrades: invitationGradesResult.data ?? [],
  };
}

export async function getInviters(inviterIds: string[]) {
  const supabase = await createClient();
  if (!inviterIds.length) return [];

  const { data } = await supabase
    .from("profiles")
    .select("id, display_name, email")
    .in("id", inviterIds);
  return data ?? [];
}

