import { createClient } from "@/lib/supabase/server";
import {
  DIMENSION_KEY_ORDER,
  DIMENSION_LABELS,
  type AnalyticsData,
  type Classification,
  type DimensionKey,
  type DistributionSlice,
  type TrendPoint,
} from "../_lib/analytics-types";
import { isAnalysisPayload, normalizeStatus, type AnalysisPayload } from "@/app/(dashboard)/lessons/[id]/_lib/analysis-types";

export async function getAnalytics(): Promise<AnalyticsData> {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user) {
    return emptyData();
  }

  const { data, error } = await supabase
    .from("lessons")
    .select(`
      id,
      title,
      created_at,
      lesson_analyses ( id, payload, created_at )
    `)
    .order("created_at", { referencedTable: "lesson_analyses", ascending: false })
    .limit(1, { referencedTable: "lesson_analyses" });

  if (error || !data) {
    console.error("getAnalytics: supabase fetch error", error);
    return emptyData();
  }

  const analysedLessons = data
    .filter((l) => l.lesson_analyses && l.lesson_analyses.length > 0)
    .map((l) => ({
      id: l.id,
      title: l.title ?? "Untitled",
      date: l.created_at ?? new Date().toISOString(),
      analysis: l.lesson_analyses[0],
    }));

  if (analysedLessons.length === 0) {
    return emptyData();
  }

  const payloads: { lessonId: string; title: string; date: string; payload: AnalysisPayload }[] = [];
  for (const lesson of analysedLessons) {
    const raw = lesson.analysis.payload;
    if (isAnalysisPayload(raw)) {
      payloads.push({
        lessonId: lesson.id,
        title: lesson.title,
        date: lesson.date,
        payload: raw,
      });
    }
  }

  if (payloads.length === 0) {
    return emptyData();
  }

  const totalLessons = payloads.length;
  const scores = payloads.map((p) => p.payload.overall_score);
  const averageScore = round1(toPct(scores.reduce((a, b) => a + b, 0) / scores.length));

  const classificationCounts: Record<Classification, number> = {
    excellent: 0,
    good: 0,
    satisfactory: 0,
    needs_improvement: 0,
  };
  for (const p of payloads) {
    const status = normalizeStatus(p.payload.classification);
    classificationCounts[status]++;
  }
  const topRatedCount = classificationCounts.excellent + classificationCounts.good;

  const distribution: DistributionSlice[] = (
    ["excellent", "good", "satisfactory", "needs_improvement"] as Classification[]
  )
    .filter((c) => classificationCounts[c] > 0)
    .map((c) => ({
      classification: c,
      count: classificationCounts[c],
      pct: Math.round((classificationCounts[c] / totalLessons) * 100),
    }));

  const dimensionScores: Record<DimensionKey, number[]> = {} as Record<DimensionKey, number[]>;
  for (const key of DIMENSION_KEY_ORDER) {
    dimensionScores[key] = [];
  }

  const keyMap: Record<string, DimensionKey> = {
    lesson_structure: "lesson_structure",
    behaviour_management: "behaviour_management",
    clarity: "clarity",
    formative_assessment: "formative_assessment",
    engagement: "engagement",
    technology: "technology",
  };

  for (const p of payloads) {
    for (const metric of p.payload.metrics) {
      const dimKey = keyMap[metric.name];
      if (dimKey) {
        dimensionScores[dimKey].push(toPct(metric.score));
      }
    }
  }

  const dimensions = DIMENSION_KEY_ORDER.map((key) => ({
    key,
    label: DIMENSION_LABELS[key],
    score: round1(
      dimensionScores[key].length > 0
        ? dimensionScores[key].reduce((a, b) => a + b, 0) / dimensionScores[key].length
        : 0,
    ),
  }));

  let primaryFocus = dimensions[0];
  for (const dim of dimensions) {
    if (dim.score < primaryFocus.score) {
      primaryFocus = dim;
    }
  }

  const trend: TrendPoint[] = payloads
    .map((p) => ({
      lessonId: p.lessonId,
      title: p.title,
      date: p.date,
      score: round1(toPct(p.payload.overall_score)),
    }))
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return {
    kpis: {
      totalLessons,
      averageScore,
      topRatedCount,
      primaryFocus: {
        key: primaryFocus.key,
        label: primaryFocus.label,
        score: primaryFocus.score,
      },
    },
    dimensions,
    overallScore: averageScore,
    distribution,
    trend,
    isEmpty: false,
    hasSummaryData: totalLessons >= 3,
  };
}

function emptyData(): AnalyticsData {
  return {
    kpis: {
      totalLessons: 0,
      averageScore: 0,
      topRatedCount: 0,
      primaryFocus: { key: "clarity", label: "Clarity", score: 0 },
    },
    dimensions: DIMENSION_KEY_ORDER.map((key) => ({
      key,
      label: DIMENSION_LABELS[key],
      score: 0,
    })),
    overallScore: 0,
    distribution: [],
    trend: [],
    isEmpty: true,
    hasSummaryData: false,
  };
}

function toPct(score: number): number {
  if (score > 1) return score;
  return score * 100;
}

function round1(n: number): number {
  return Math.round(n * 10) / 10;
}

