export type PerformanceSummary = {
  key_strengths: { text: string; dimension: string }[];
  areas_for_improvement: { text: string; dimension: string }[];
};

export type AnalysisPayload = {
  lesson_id: string;
  overall_score: number;
  classification: string;
  summary: string;
  metrics: AnalysisMetric[];
  performance_summary: PerformanceSummary;
};

/** Map new schema metric key → old DimensionName */
export const METRIC_TO_DIMENSION: Record<MetricKey, DimensionName> = {
  lesson_structure: "structure",
  behaviour_management: "management",
  clarity: "clarity",
  formative_assessment: "assessment",
  engagement: "engagement",
  technology: "technology",
};

export function isAnalysisPayload(value: unknown): value is AnalysisPayload {
  if (!value || typeof value !== "object") return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.lesson_id === "string" &&
    typeof v.overall_score === "number" &&
    typeof v.classification === "string" &&
    typeof v.summary === "string" &&
    Array.isArray(v.metrics) &&
    v.metrics.length === 6 &&
    v.metrics.every(
      (m: unknown) =>
        !!m &&
        typeof m === "object" &&
        typeof (m as Record<string, unknown>).name === "string" &&
        typeof (m as Record<string, unknown>).score === "number" &&
        typeof (m as Record<string, unknown>).label === "string" &&
        typeof (m as Record<string, unknown>).narrative === "string" &&
        Array.isArray((m as Record<string, unknown>).factors),
    ) &&
    !!v.performance_summary &&
    typeof v.performance_summary === "object"
  );
}

