            </p>
            <TrendChart trend={aggregate.trend} averageScore={aggregate.kpis.averageScore} />
          </div>

          {/* Teacher breakdown */}
          <TeacherBreakdownTable teachers={teachers} getTeacherHref={getTeacherHref} />
        </div>
      )}
    </div>
  );
}

